{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbf9;--card:#fff;--ink:#111;--muted:#556;--accent:#2b7a5e;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:var(--ink);background:linear-gradient(180deg,#fbfff9 0%, #f7fbf8 100%);-webkit-font-smoothing:antialiased}
    header{position:sticky;top:0;backdrop-filter: blur(6px);background:linear-gradient(180deg,rgba(255,255,255,.6),rgba(255,255,255,.4));border-bottom:1px solid rgba(16,24,32,.04);z-index:40}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:14px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;display:inline-grid;place-items:center;border-radius:10px;background:linear-gradient(135deg,var(--accent),#54a67f);color:white;font-weight:700}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:600}
    .cta a{background:var(--accent);color:white;padding:9px 14px;border-radius:8px;text-decoration:none;font-weight:700}

    main{max-width:1100px;margin:36px auto;padding:18px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center;background:var(--card);padding:28px;border-radius:14px;box-shadow:0 6px 30px rgba(11,20,15,.06);position:relative;overflow:hidden}
    .hero .lead{font-size:20px;color:var(--muted)}
    .hero h1{margin:6px 0;font-size:28px}
    .muted{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(12,1fr);gap:18px}
    .col-7{grid-column:span 7}
    .col-5{grid-column:span 5}
    .card{background:linear-gradient(180deg,var(--card),#fbfffd);padding:18px;border-radius:12px;border:1px solid rgba(13,20,18,.03)}

    /* pattern via inline data uri */
    .pattern-block{background-image:url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='400' height='400' viewBox='0 0 400 400'%3E%3Cdefs%3E%3Cpattern id='p' width='80' height='80' patternUnits='userSpaceOnUse'%3E%3Crect width='80' height='80' fill='%23f6fff8'/%3E%3Ccircle cx='12' cy='12' r='3' fill='%232b7a5e' opacity='0.08'/%3E%3Ccircle cx='68' cy='68' r='2.5' fill='%2354a67f' opacity='0.06'/%3E%3Cpath d='M0 40 Q20 20 40 40 T80 40' fill='none' stroke='%232b7a5e' stroke-opacity='0.03' stroke-width='1'/%3E%3C/pattern%3E%3C/defs%3E%3Crect width='100%25' height='100%25' fill='url(%23p)'/%3E%3C/svg%3E");background-repeat:repeat;border-radius:10px}

    .services-list{display:grid;gap:12px}
    .service{display:flex;gap:12px;align-items:flex-start;padding:12px;border-radius:10px;border:1px solid rgba(8,12,10,.03);background:linear-gradient(180deg,rgba(255,255,255,.8),rgba(255,255,255,.9))}
    .pill{background:var(--glass);padding:8px;border-radius:8px;color:var(--accent);font-weight:700}

    .plan-builder{display:flex;flex-direction:column;gap:12px}
    label{font-weight:700;font-size:13px;color:var(--muted)}
    input[type="text"],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,.06);background:white}
    .checks{display:flex;flex-wrap:wrap;gap:8px}
    .checks label{background:#f3faf6;padding:8px 10px;border-radius:8px;border:1px solid rgba(43,122,94,.06);cursor:pointer}
    button{background:var(--accent);border:none;color:white;padding:10px 12px;border-radius:10px;font-weight:700;cursor:pointer}
    .secondary{background:#eefbf5;color:var(--accent);border:1px solid rgba(43,122,94,.08)}
    .output{white-space:pre-wrap;background:#fff;border:1px dashed rgba(0,0,0,.04);padding:12px;border-radius:8px}

    footer{max-width:1100px;margin:28px auto;padding:18px;color:var(--muted);font-size:14px}

    /* reveal effect */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .55s ease,transform .55s ease}
    .reveal.reveal--visible{opacity:1;transform:none}

    @media(min-width:880px){.hero{grid-template-columns:1fr 320px}.col-7{grid-column:span 7}.col-5{grid-column:span 5}}    
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">
        <div class="logo">HM</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav aria-label="Primary navigation">
        <a href="index.html">Home</a>
        <a href="services.html" aria-current="page">Services & Paths</a>
        <a href="conditions.html">Conditions</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="cta"><a href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
    </div>
  </header>

  <main>
    <section class="hero card pattern-block reveal" data-reveal>
      <div style="display:flex;gap:18px;align-items:flex-start;">
        <div style="flex:1">
          <div class="lead">Tailored paths for integrated wellbeing</div>
          <h1>Practical session paths that meet you where you are</h1>
          <p class="muted">We combine lifestyle guidance, evidence-informed whole-person tools, and practical follow-through to design short-term plans and deeper courses of care. Nothing prescriptive — just structured support you can try and adapt.</p>
          <div style="margin-top:12px;display:flex;gap:10px">
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a Focus Session</a>
            <a class="secondary" href="about.html">Meet the team</a>
          </div>
        </div>
        <aside style="width:240px">
          <div class="card">
            <div style="font-size:13px;color:var(--muted)">Quick snapshot</div>
            <div style="margin-top:8px;font-weight:800;font-size:18px">Short Sessions — Focused tracks — Home-friendly steps</div>
            <ul style="margin-top:10px;color:var(--muted)">
              <li>Flexible scheduling across in-person and virtual</li>
              <li>Clear, actionable recommendations after every visit</li>
            </ul>
          </div>
        </aside>
      </div>
    </section>

    <section class="card reveal" data-reveal style="margin-top:18px">
      <div class="grid">
        <div class="col-7">
          <h3 style="margin:0 0 8px 0">Session Planner</h3>
          <p class="muted" style="margin-top:0">Build a personalized session outline in moments — copy it to bring to your visit or to share with a provider.</p>

          <div class="plan-builder" id="planner">
            <div>
              <label for="concern">Primary concern (brief)</label>
              <input id="concern" type="text" placeholder="e.g., sleep fragmentation, chronic bloating, anxiety spikes">
            </div>
            <div>
              <label>Modalities to include</label>
              <div class="checks">
                <label><input type="checkbox" value="Functional nutrition"> Functional nutrition</label>
                <label><input type="checkbox" value="Targeted botanicals"> Targeted botanicals</label>
                <label><input type="checkbox" value="Movement therapy"> Movement therapy</label>
                <label><input type="checkbox" value="Breath & mindfulness"> Breath & mindfulness</label>
                <label><input type="checkbox" value="Lab review"> Lab review</label>
              </div>
            </div>
            <div style="display:flex;gap:10px">
              <div style="flex:1">
                <label>Session length</label>
                <select id="length"><option value="25">25 minutes — Focus Session</option><option value="50">50 minutes — Full Visit</option><option value="90">90 minutes — Deep Intake</option></select>
              </div>
              <div style="width:160px">
                <label>Frequency</label>
                <select id="frequency"><option>Once</option><option>Weekly</option><option>Biweekly</option><option>Monthly</option></select>
              </div>
            </div>
            <div>
              <label for="notes">Notes / context (optional)</label>
              <textarea id="notes" rows="3" placeholder="Relevant history, current meds, rhythms you notice"></textarea>
            </div>
            <div style="display:flex;gap:10px;align-items:center">
              <button id="build">Compose plan</button>
              <button id="clear" class="secondary" type="button">Clear</button>
              <div style="margin-left:auto;color:var(--muted);font-size:13px">Local only — nothing is sent</div>
            </div>

            <div style="margin-top:12px">
              <label>Plan summary (plain text)</label>
              <div class="output" id="output" aria-live="polite">Your plan summary will appear here after you click "Compose plan".</div>
              <div style="margin-top:8px;display:flex;gap:8px">
                <button id="copy">Copy summary</button>
                <button id="download" class="secondary">Download .txt</button>
              </div>
            </div>
          </div>
        </div>
        <div class="col-5">
          <div class="card">
            <h4 style="margin-top:0">Service paths</h4>
            <div class="services-list">
              <div class="service">
                <div class="pill">Focus Session</div>
                <div>
                  <div style="font-weight:800">Short, problem-focused visit</div>
                  <div class="muted">25 minutes. For fast troubleshooting and razor-focused recommendations.</div>
                </div>
              </div>

              <div class="service">
                <div class="pill">Full Visit</div>
                <div>
                  <div style="font-weight:800">Comprehensive assessment</div>
                  <div class="muted">50 minutes. Intake-style review, personalized tasks and short-term plan.</div>
                </div>
              </div>

              <div class="service">
                <div class="pill">Intake + Follow</div>
                <div>
                  <div style="font-weight:800">Extended intake + roadmap</div>
                  <div class="muted">90 minutes. Deep context gathering, testing plan, and structured follow-up options.</div>
                </div>
              </div>
            </div>

            <div style="margin-top:12px">
              <h5 style="margin:0 0 8px 0">Investment framing</h5>
              <div class="muted">We frame pricing as commitment tiers rather than fixed promises. The right path depends on goals and testing needs.</div>
              <ul style="margin-top:8px;color:var(--muted)">
                <li>Focus Session — starting at $120</li>
                <li>Full Visit — starting at $240</li>
                <li>Intake + Follow — starting at $420</li>
              </ul>
              <a class="cta" href="pricing.html" style="display:inline-block;margin-top:10px">See full details</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="card reveal" data-reveal style="margin-top:18px">
      <h3 style="margin-top:0">How our short engagements work</h3>
      <p class="muted">Each session is designed to return you to everyday life with simple, testable steps. Recommendations are educational and tailored; they are not medical guarantees. If you have urgent concerns, please call your primary care provider or emergency services.</p>

      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px">
        <div class="card"><strong>Listen & map</strong><div class="muted">Focused intake to locate the highest-impact starting points.</div></div>
        <div class="card"><strong>Design small experiments</strong><div class="muted">Specific, measurable steps you can try at home with check-ins.</div></div>
        <div class="card"><strong>Adjust & support</strong><div class="muted">Practical tweaks and clarity on when to consider testing or referral.</div></div>
      </div>
    </section>

    <section class="reveal" data-reveal style="margin-top:18px">
      <div style="display:flex;gap:12px;align-items:center;justify-content:space-between">
        <div>
          <div style="font-weight:800">Ready to try a focused session?</div>
          <div class="muted">Book a short visit to clarify next steps and walk away with an action checklist.</div>
        </div>
        <div>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve your session</a>
        </div>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      // Scroll reveal with prefers-reduced-motion support
      var prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('[data-reveal]');
      if(prefersReduce){reveals.forEach(function(r){r.classList.add('reveal--visible')});return}
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('reveal--visible'); io.unobserve(e.target); } });
      },{threshold:0.12});
      reveals.forEach(function(r){ io.observe(r); });

      // Session Planner
      var build = document.getElementById('build');
      var clear = document.getElementById('clear');
      var copy = document.getElementById('copy');
      var download = document.getElementById('download');
      var output = document.getElementById('output');
      function gather(){
        var concern = document.getElementById('concern').value.trim();
        var length = document.getElementById('length').value;
        var frequency = document.getElementById('frequency').value;
        var notes = document.getElementById('notes').value.trim();
        var checked = Array.from(document.querySelectorAll('#planner .checks input:checked')).map(function(i){return i.value});
        return {concern,length,frequency,notes,checked};
      }
      function compose(){
        var g = gather();
        var lines = [];
        lines.push('Session plan — generated locally');
        lines.push('------------------------------');
        if(g.concern) lines.push('Primary concern: ' + g.concern);
        lines.push('Session length: ' + g.length + ' minutes (' + (g.length==25? 'Focus Session': g.length==50? 'Full Visit': 'Deep Intake') + ')');
        lines.push('Frequency: ' + g.frequency);
        if(g.checked.length) lines.push('Modalities: ' + g.checked.join(', '));
        if(g.notes) lines.push('\nNotes:\n' + g.notes);
        lines.push('\nSuggested next steps:');
        lines.push('- Clarify 1–2 behaviors to track for 7–14 days');
        lines.push('- Try 1 targeted adjustment or micro-practice and note response');
        lines.push('- Consider follow-up or testing if no response after two cycles');
        return lines.join('\n');
      }
      build.addEventListener('click',function(){ output.textContent = compose(); });
      clear.addEventListener('click',function(){ document.getElementById('concern').value=''; document.getElementById('notes').value=''; document.querySelectorAll('#planner .checks input').forEach(function(i){i.checked=false}); output.textContent='Your plan summary will appear here after you click "Compose plan".'; });
      copy.addEventListener('click',function(){ var txt = output.textContent; if(!txt) return; navigator.clipboard && navigator.clipboard.writeText(txt).then(function(){ copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy summary'},1200); }).catch(function(){ /* fall back */ var ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select(); try{document.execCommand('copy'); copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy summary'},1200);}catch(e){} document.body.removeChild(ta); }); });
      download.addEventListener('click',function(){ var txt = output.textContent; if(!txt) return; var blob = new Blob([txt],{type:'text/plain'}); var url = URL.createObjectURL(blob); var a = document.createElement('a'); a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); setTimeout(function(){URL.revokeObjectURL(url); document.body.removeChild(a);},300);
      });
    })();
  </script>
</body>
</html>"} 
